# --- format_duration ---


class TestFormatDuration:
    def test_zero(self) -> None:
        assert format_duration(0) == "0s"

    def test_seconds_only(self) -> None:
        assert format_duration(45) == "45s"

    def test_minutes_and_seconds(self) -> None:
        assert format_duration(125) == "2m5s"

    def test_hours_and_minutes(self) -> None:
        assert format_duration(3720) == "1h2m"

    def test_days_and_hours(self) -> None:
        assert format_duration(90000) == "1d1h"

    def test_max_two_units(self) -> None:
        # 1d 2h 3m 4s => "1d2h" (only first two)
        assert format_duration(93784) == "1d2h"

    def test_negative_clamps_to_zero(self) -> None:
        assert format_duration(-100) == "0s"

    def test_exact_hour(self) -> None:
        assert format_duration(3600) == "1h"

    def test_exact_day(self) -> None:
        assert format_duration(86400) == "1d"


