# --- get_usage ---


class TestGetUsage:
    def test_returns_none_when_no_data(self) -> None:
        with (
            patch(
                "personal_assistant_dashboard.usage_poller._read_cache",
                return_value=None,
            ),
            patch(
                "personal_assistant_dashboard.usage_poller._fetch_usage",
                return_value=None,
            ),
        ):
            assert get_usage() is None

    def test_returns_fresh_cache(self) -> None:
        cached = {
            "response_data": {
                "five_hour": {
                    "utilization": 42.0,
                    "resets_at": None,
                }
            },
            "last_success_at": time.time(),
            "last_attempt_at": time.time(),
            "consecutive_failures": 0,
        }
        with (
            patch(
                "personal_assistant_dashboard.usage_poller._read_cache",
                return_value=cached,
            ),
            patch(
                "personal_assistant_dashboard.usage_poller._fetch_usage"
            ) as mock_fetch,
        ):
            result = get_usage()
            mock_fetch.assert_not_called()
        assert result is not None
        assert result.utilization == 42.0
        assert result.is_stale is False

    def test_fetches_when_cache_expired(self) -> None:
        cached = {
            "response_data": {"five_hour": {"utilization": 10.0, "resets_at": None}},
            "last_success_at": time.time() - CACHE_TTL_SECONDS - 10,
            "last_attempt_at": time.time() - CACHE_TTL_SECONDS - 10,
            "consecutive_failures": 0,
        }
        fresh = {"five_hour": {"utilization": 55.0, "resets_at": None}}
        with (
            patch(
                "personal_assistant_dashboard.usage_poller._read_cache",
                return_value=cached,
            ),
            patch(
                "personal_assistant_dashboard.usage_poller._fetch_usage",
                return_value=fresh,
            ),
            patch("personal_assistant_dashboard.usage_poller._write_cache"),
        ):
            result = get_usage()
        assert result is not None
        assert result.utilization == 55.0
        assert result.is_stale is False

    def test_serves_stale_on_fetch_failure(self) -> None:
        cached = {
            "response_data": {"five_hour": {"utilization": 30.0, "resets_at": None}},
            "last_success_at": time.time() - CACHE_TTL_SECONDS - 10,
            "last_attempt_at": time.time() - CACHE_TTL_SECONDS - 10,
            "consecutive_failures": 0,
        }
        with (
            patch(
                "personal_assistant_dashboard.usage_poller._read_cache",
                return_value=cached,
            ),
            patch(
                "personal_assistant_dashboard.usage_poller._fetch_usage",
                return_value=None,
            ),
            patch("personal_assistant_dashboard.usage_poller._write_cache"),
        ):
            result = get_usage()
        assert result is not None
        assert result.utilization == 30.0
        assert result.is_stale is True


